// src/pages/Cart.jsx

import React from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { removeFromCart, updateQuantity } from '../features/cartSlice';

const Cart = () => {
  const cartItems = useSelector(state => state.cart.items);
  const dispatch = useDispatch();

  return (
    <div className="cart-container text-center">
      <h1>Your Cart</h1>
      <p>Review your selected books before checkout.</p>

      {cartItems.length === 0 ? (
        <p>Your cart is empty.</p>
      ) : (
        <ul className="cart-list">
          {cartItems.map(item => (
            <li key={item.key} className="cart-item">
              <img src={item.coverUrl} alt={item.title} className="cart-image" />
              <div className="cart-details">
                <h3>{item.title}</h3>
                <p><strong>Author:</strong> {item.author}</p>
                <p><strong>Published:</strong> {item.publishYear}</p>
                <p><strong>Quantity:</strong></p>
                <input
                  type="number"
                  value={item.quantity}
                  min="1"
                  onChange={e =>
                    dispatch(updateQuantity({ key: item.key, quantity: parseInt(e.target.value) }))
                  }
                />
                <button onClick={() => dispatch(removeFromCart(item.key))}>
                  Remove
                </button>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Cart;
